sys_script_email.script:
(function runMailScript(current, template, email, email_action, event) {

    var users = JSON.parse(event.parm2);

    template.print(
        '<p style="margin-bottom:15px;">' +
        'The following team members are missing certifications:' +
        '</p>'
    );

    template.print(
        '<table cellpadding="0" cellspacing="0" style="width:100%; border-collapse:collapse; border:1px solid #dcdcdc; font-family:Arial,Helvetica,sans-serif;">' +
            '<tr style="background-color:#032D42; color:#ffffff;">' +
                '<th style="padding:12px; text-align:left; border:1px solid #032D42;">User</th>' +
                '<th style="padding:12px; text-align:left; border:1px solid #032D42;">Missing Certification(s)</th>' +
            '</tr>'
    );

    for (var i = 0; i < users.length; i++) {

        var bgColor = (i % 2 === 0) ? '#f8f9fa' : '#ffffff';

        template.print(
            '<tr style="background-color:' + bgColor + ';">' +
                '<td style="padding:10px; border:1px solid #dcdcdc;">' + users[i].user + '</td>' +
                '<td style="padding:10px; border:1px solid #dcdcdc;">' + users[i].missing + '</td>' +
            '</tr>'
        );
    }

    template.print('</table>');

})(current, template, email, email_action, event);
